 static int checks;static void Check(bool value,string label){if(!value)throw new Exception("M FAIL: "+label);checks++;Console.WriteLine("M PASS: "+label);}
 static DemoWorld World(){var w=new DemoWorld();w.NewGame(0);w.SimulationPaused=true;w.WalletFunds=2000000;w.Player.CargoMax=100000;foreach(var a in w.WorldAgents44.Where(a=>a.Station==w.StationKey44)){w.AgentsState.Standings[a.Id]=8;w.AgentsState.Standings[a.Corporation]=8;w.AgentsState.Standings[a.Faction]=8;}return w;}
 static Mission38 Offer(DemoWorld w,string id){Check(w.RequestReviewedM(id)=="","local agent offers "+id);return w.AgentsState.Missions.Last();}
 static void Enter(DemoWorld w,Mission38 m){Check(w.AcceptMission38(m.Id)=="","accept "+m.Definition);w.Undock();w.EnterGrid(m.WarpId,false);}
 static void Dock(DemoWorld w,Mission38 m){w.SystemId=Stations44.SystemOf(m.Destination);w.StationId=w.ImportedWorld43?m.Destination:"";w.Grid=w.ImportedWorld43?m.Destination:"station";w.Screen=ViewMode.Station;}
 static void Pickup(DemoWorld w,Mission38 m){w.Player.Position=w.Targets.First(t=>t.Id==m.WarpId+":objective").Position;Check(w.CollectMissionObjective38(m.Id)=="","physical collection "+m.Definition);}
 static void FinishStep(DemoWorld w,Mission38 m){Enter(w,m);if(m.ProfileM!.Mode=="Retrieve")Pickup(w,m);else if(m.ProfileM.Mode=="Combat")foreach(var t in w.Targets.Where(t=>t.Kind==TargetKind.Raider&&t.Alive).ToArray())w.DamageMissionAudit38(t);else if(m.ProfileM.Mode=="Courier"){Dock(w,m);w.Grid="station";w.SystemId=Stations44.SystemOf(m.Pickup);Check(w.TransferMissionCargo38(m.Id,true,m.Spec.Volume)=="","chain courier load");}Dock(w,m);Check(w.CompleteMission38(m.Id)=="","chain step settles once");}
