  var previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string dir=Path.Combine(Path.GetTempPath(),"stage-m-"+Guid.NewGuid().ToString("N"));Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);SkillCatalog.VerificationAllV=false;
  try{
   Check(MissionCatalogM.Load().Count==22,"22 explicit Stage M profiles loaded");Check(AgentCatalog38.Missions.Values.Count(d=>d.ProfileM==null)==674,"673 inherited rows and authored L relay remain distinguishable");
   foreach(var d in AgentCatalog38.Missions.Values){var g=GraphCompilerL.Mission(new(){Definition=d.Id});Check(GraphCompilerL.Validate(g)=="","valid graph "+d.Id);}
   var w=World();var m=Offer(w,"m_cargo1");Check(m.DefinitionSnapshotM!=null&&m.Spec!=AgentCatalog38.Missions[m.Definition],"offered contract owns a copied full content definition");Enter(w,m);Check(!w.Targets.Any(t=>t.Kind==TargetKind.Raider)&&w.Targets.Any(t=>t.Kind==TargetKind.Container),"L1 warehouse available before any hostile spawn");Check(w.CollectMissionObjective38(m.Id)!="","remote collection rejected");Pickup(w,m);Check(m.Cargo==1&&m.ObjectiveDone&&w.Targets.Count(t=>t.Kind==TargetKind.Raider)==7,"collection spawns first wave without a kill-all requirement");Check(w.CollectMissionObjective38(m.Id)!=""&&m.Cargo==1,"duplicate collection cannot mint cargo");var first=w.Targets.First(t=>t.Kind==TargetKind.Raider);w.DamageMissionAudit38(first);Check(w.Targets.Count(t=>t.Kind==TargetKind.Raider&&t.Alive)==14,"reinforcement trigger remains active after objective recovery");w.Save();var loaded=new DemoWorld();Check(loaded.Load(),"M mission save loads");var lm=loaded.AgentsState.Missions.Single(x=>x.Id==m.Id);Check(lm.ProfileM?.CargoName=="Synthetic Oil"&&lm.GraphL!.Generated.Count==15,"pinned profile and generated waves survive reload");Dock(loaded,lm);decimal before=loaded.Balance;Check(loaded.CompleteMission38(lm.Id)==""&&loaded.Balance==before+lm.Reward+lm.Bonus,"blitz turn-in pays with surviving enemies");Check(loaded.CompleteMission38(lm.Id)!="","second turn-in blocked");
   var loss=World();var ml=Offer(loss,"m_cargo2");Enter(loss,ml);Pickup(loss,ml);loss.LoseMissionCargo38();Dock(loss,ml);Check(loss.CompleteMission38(ml.Id)!=""&&ml.State=="Accepted","cargo loss blocks recovered-objective settlement");
   var m2w=World();var m2=Offer(m2w,"m_cargo2");Enter(m2w,m2);Pickup(m2w,m2);int generated=m2.GraphL!.Generated.Count;m2w.DamageMissionAudit38(m2w.Targets.First(t=>t.Kind==TargetKind.Raider&&m2.GraphL.Npcs[t.Id].Hull=="frigate"));Check(m2.GraphL.Generated.Count==generated,"L2 frigate kill does not trigger heavy reinforcement");m2w.DamageMissionAudit38(m2w.Targets.First(t=>t.Kind==TargetKind.Raider&&m2.GraphL.Npcs[t.Id].Hull=="destroyer"));Check(m2.GraphL.Generated.Count>generated,"L2 destroyer kill triggers reviewed reinforcement");
