   var collateral=World();var c4=Offer(collateral,"m_goods4");decimal money=collateral.Balance;Check(collateral.AcceptMission38(c4.Id)==""&&collateral.Balance==money-1000000&&c4.CollateralHeldM==1000000,"L4 escrow debited once");Check(collateral.AcceptMission38(c4.Id)!=""&&collateral.Balance==money-1000000,"duplicate acceptance cannot debit twice");collateral.TransferMissionCargo38(c4.Id,true,5000);Dock(collateral,c4);Check(collateral.CompleteMission38(c4.Id)==""&&c4.CollateralHeldM==0&&collateral.Balance==money+c4.Reward+c4.Bonus,"successful courier returns collateral once");
   var poor=World();poor.WalletFunds=1;var pc=Offer(poor,"m_goods4");Check(poor.AcceptMission38(pc.Id)!=""&&pc.State=="Offered","insufficient collateral cannot accept");
