   var chain=World();Check(chain.StartChainM("horizons")=="","epic adaptation starts through ordinary local contact");var run=chain.AgentsState.ChainsM.Last();FinishStep(chain,chain.AgentsState.Missions.Last());Check(run.Completed.SequenceEqual(new[]{"recover"})&&run.Mission=="","first step completion persisted");Check(chain.ContinueChainM(run.Id,"invalid")!=""&&run.Choices.Count==0,"invalid branch rejected");Check(chain.ContinueChainM(run.Id,"Negotiate passage")==""&&run.Choices["recover"]=="Negotiate passage","branch commits only after successful next offer");FinishStep(chain,chain.AgentsState.Missions.Last());chain.SystemId=Stations44.SystemOf(run.Origin);chain.Grid="station";Check(chain.ContinueChainM(run.Id)=="","contact continues final step");FinishStep(chain,chain.AgentsState.Missions.Last());Check(run.State=="Completed"&&run.Completed.Count==3,"chosen epic path completes exactly three steps");Check(chain.StartChainM("horizons")!="","90 day replay lock enforced");chain.Save();var chainLoad=new DemoWorld();Check(chainLoad.Load()&&chainLoad.AgentsState.ChainsM.Last().Choices.Count==1,"chain decisions and repeat lock reload");chain.SimulationUtc=run.RepeatAfter.AddSeconds(1);Check(chain.StartChainM("horizons")=="","arc becomes replayable on local clock");
   var cosmos=World();Check(cosmos.StartChainM("custodian")=="","one-time special chain starts");var cr=cosmos.AgentsState.ChainsM.Last();var co=cosmos.AgentsState.Missions.Last();cosmos.AcceptMission38(co.Id);cosmos.QuitMission38(co.Id);Check(cr.State=="Failed"&&cosmos.StartChainM("custodian")!="","one-time failure permanently closes chain");
   var task=World();Check(task.StartChainM("career_explorer")=="","explorer chain starts");var tm=task.AgentsState.Missions.Last();task.AcceptMission38(tm.Id);Check(task.CompleteMission38(tm.Id)!="","training cannot settle before actual activity");task.RecordTaskM("Manufacture");Check(!tm.ObjectiveDone,"unrelated activity cannot satisfy task");task.RecordTaskM("Hack");Check(task.CompleteMission38(tm.Id)=="","matching actual activity allows training turn-in");
   foreach(string branch in new[]{"Confront pursuers"}){var alt=World();alt.StartChainM("horizons");var ar=alt.AgentsState.ChainsM.Last();FinishStep(alt,alt.AgentsState.Missions.Last());Check(alt.ContinueChainM(ar.Id,branch)=="","alternate epic path offered");FinishStep(alt,alt.AgentsState.Missions.Last());Check(alt.ContinueChainM(ar.Id)=="","alternate path reaches final");FinishStep(alt,alt.AgentsState.Missions.Last());Check(ar.State=="Completed"&&ar.Choices["recover"]==branch,"combat epic branch completes");}
   foreach(var definition in MissionCatalogM.Chains.Where(d=>d.Id!="horizons")){var cw=World();Check(cw.StartChainM(definition.Id)=="","start supported chain "+definition.Id);var rr=cw.AgentsState.ChainsM.Last();while(rr.State=="Active") {var current=cw.AgentsState.Missions.Single(x=>x.Id==rr.Mission);if(current.ProfileM!.Mode=="Task"){cw.AcceptMission38(current.Id);cw.RecordTaskM(current.ProfileM.Task);Check(cw.CompleteMission38(current.Id)=="","task step settles "+definition.Id);}else if(current.ProfileM.Mode=="Mining"){Enter(cw,current);foreach(var rock in cw.Targets.Where(t=>t.Kind==TargetKind.Asteroid).ToArray())cw.HarvestMission38(rock,rock.Ore);Dock(cw,current);Check(cw.CompleteMission38(current.Id)=="","mining training settles");}else FinishStep(cw,current);if(rr.State=="Active"){cw.SystemId=Stations44.SystemOf(rr.Origin);cw.Grid="station";Check(cw.ContinueChainM(rr.Id)=="","next supported step "+definition.Id);}}Check(rr.State=="Completed"&&rr.Completed.Count==definition.Steps.Count,"all supported steps complete "+definition.Id);Check(cw.StartChainM(definition.Id)!="","one-time replay rejected "+definition.Id);}
   var units=World();var um=Offer(units,"m_goods2");units.AcceptMission38(um.Id);Check(units.InventoryDisplayCount("mission-cargo:"+um.Id,true)==20&&units.InventoryDisplayVolume("mission-cargo:"+um.Id)==10,"inventory projects discrete units and volume");Check(units.TransferBatchK(new[]{("mission-cargo:"+um.Id,10m)},true)==""&&um.Cargo==100,"atomic inventory transfer translates units to physical volume");
   var production=World();production.Skills.Grant(SkillCatalog.All.Select(s=>new SkillRequirement(s.Id,5)));production.SyncSkills();var pm=Offer(production,"m_manufacture");production.AcceptMission38(pm.Id);Check(production.BuyBlueprint("miner")=="","manufacturing training buys a real blueprint");var bp=production.Industry.Blueprints.Last();foreach(var input in IndustryCatalog37.Recipes["miner"].Minerals)production.Hangar[input.Key]=input.Value*2;Check(production.InstallIndustry(bp.Id,IndustryActivity.Manufacturing)=="","manufacturing training installs real job");var job=production.Industry.Jobs.Last();production.SimulationUtc=job.FinishUtc.AddSeconds(1);production.UpdateIndustry(production.Now);Check(production.DeliverIndustry(job.Id)==""&&pm.ObjectiveDone,"real industry delivery signals accepted training contract");
   var intrusion=World();intrusion.UtilityTrial("cruiser");var analyzer=UtilityCatalog.All.First(d=>d.Kind=="Data");intrusion.FitUtility(analyzer.Id,true,6);var im=Offer(intrusion,"m_hack");intrusion.AcceptMission38(im.Id);intrusion.EnterUtilityRange();var target=intrusion.Targets.First(t=>t.Id=="ut_Data");intrusion.Player.Position=target.Position;intrusion.SelectedId=intrusion.LockedId=target.Id;Check(intrusion.ToggleUtility(6),"training uses real analyzer activation");var board=intrusion.UtilityHackState!;int core=Array.FindIndex(board.Nodes,n=>n.Kind=="Core");for(int i=1;i<49;i++)if(i!=core)board.Nodes[i]=new(){Kind="Empty"};for(int i=1;i<49;i++)if(i!=core)intrusion.ClickUtilityHack(i);for(int i=0;i<20&&!board.Complete;i++)intrusion.ClickUtilityHack(core);Check(board.Won&&im.ObjectiveDone,"real hack success signals training; unobstructed board is a test fixture");
   var laser=World();var laserMission=Offer(laser,"m_mine1");Enter(laser,laserMission);var laserRock=laser.Targets.First(t=>t.Kind==TargetKind.Asteroid);laser.Player.Position=laserRock.Position;laser.SelectedId=laser.LockedId=laserRock.Id;laser.Player.MiningTimer=0;laser.Player.MinerOn=true;laser.SimulationPaused=false;laser.Update(.1f);Check(laserMission.Harvested>0&&laserMission.Cargo==laserMission.Harvested,"actual legacy miner cycle fills bound multi-deposit cargo");
   var iceWorld=World();iceWorld.Skills.Grant(SkillCatalog.All.Select(s=>new SkillRequirement(s.Id,5)));iceWorld.SyncSkills();iceWorld.UtilityTrial("mining_barge");iceWorld.Player.UtilityFit="";iceWorld.Player.Missiles=0;var iceModule=UtilityCatalog.All.First(d=>d.Kind=="IceHarvest");Check(iceWorld.FitUtility(iceModule.Id,true,0),"fit native ice harvester for mission / "+iceWorld.UtilityFitError(iceModule,0));var iceMission=Offer(iceWorld,"m_mine4");Enter(iceWorld,iceMission);var iceRock=iceWorld.Targets.First(t=>t.Kind==TargetKind.Asteroid);iceWorld.Player.Position=iceRock.Position;iceWorld.SelectedId=iceWorld.LockedId=iceRock.Id;Check(iceWorld.ToggleUtility(0),"native ice mission cycle starts");iceWorld.UpdateUtility(iceWorld.Player.Utilities[0].CycleDuration+.1f);Check(iceMission.Cargo>=1000&&iceMission.Cargo%1000==0&&iceWorld.InventoryDisplayCount("mission-cargo:"+iceMission.Id,false)>=1,"native ice cycle delivers whole mission blocks");
